import { clsx } from "clsx";
import {
  ChevronDown,
  CircleAlert,
  CircleCheck,
  Ellipsis,
  type LucideIcon,
  Plus,
  Search,
  Trash2,
  Users,
  X,
} from "lucide-react";
import type { ComponentPropsWithRef } from "react";

import "./icon.css";

const iconMap = {
  plus: Plus,
  close: X,
  success: CircleCheck,
  error: CircleAlert,
  users: Users,
  search: Search,
  ellipsis: Ellipsis,
  "chevron-down": ChevronDown,
  trash: Trash2,
} as const satisfies Record<string, LucideIcon>;

export type IconName = keyof typeof iconMap;

export type IconProps = Omit<ComponentPropsWithRef<"svg">, "children"> & {
  name: IconName;
  size?: "sm" | "md" | "lg";
  label?: string;
};

export function Icon({ className, label, name, size = "md", ...props }: IconProps) {
  const Glyph = iconMap[name];

  return (
    <Glyph
      {...props}
      aria-hidden={label ? undefined : true}
      aria-label={label}
      className={clsx("mfd-icon", className)}
      data-size={size}
      role={label ? "img" : undefined}
      strokeWidth={2}
    />
  );
}

export type IconButtonProps = Omit<ComponentPropsWithRef<"button">, "aria-label"> & {
  label: string;
  size?: "sm" | "md" | "lg";
};

export function IconButton({
  children,
  className,
  label,
  size = "md",
  type = "button",
  ...props
}: IconButtonProps) {
  return (
    <button
      {...props}
      aria-label={label}
      className={clsx("mfd-icon-button", className)}
      data-size={size}
      type={type}
    >
      {children}
    </button>
  );
}

.mfd-icon {
  flex: none;
  height: var(--mfd-icon-size-md);
  width: var(--mfd-icon-size-md);
}

.mfd-icon[data-size="sm"] {
  height: var(--mfd-icon-size-sm);
  width: var(--mfd-icon-size-sm);
}

.mfd-icon[data-size="lg"] {
  height: var(--mfd-icon-size-lg);
  width: var(--mfd-icon-size-lg);
}

.mfd-icon-button {
  align-items: center;
  background: transparent;
  border: 1px solid transparent;
  border-radius: var(--mfd-radius-control);
  color: var(--mfd-color-text-primary);
  cursor: pointer;
  display: inline-flex;
  justify-content: center;
  min-height: var(--mfd-size-hit-target-minimum);
  min-width: var(--mfd-size-hit-target-minimum);
  touch-action: manipulation;
}

.mfd-icon-button[data-size="sm"] > .mfd-icon {
  height: var(--mfd-icon-size-sm);
  width: var(--mfd-icon-size-sm);
}

.mfd-icon-button[data-size="lg"] > .mfd-icon {
  height: var(--mfd-icon-size-lg);
  width: var(--mfd-icon-size-lg);
}

@media (hover: hover) {
  .mfd-icon-button:hover:not(:disabled) {
    background: var(--mfd-color-bg-subtle);
  }
}

.mfd-icon-button:focus-visible {
  outline: 2px solid var(--mfd-color-border-focus);
  outline-offset: 2px;
}

.mfd-icon-button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}
